mapper.select:
select FINPROD_MARKET_ID id, NVL(FINPROD_ABBR, FINPROD_NAME) text, FINPROD_ID object from FIN_PRODUCT
and (instr(FINPROD_MARKET_ID, #{search}) > 0 or instr(FINPROD_ID, #{search}) > 0 or instr(FINPROD_NAME, #{search}) > 0 or instr(FINPROD_ABBR, #{search}) > 0)
and FINPROD_TYPE2 = #{finprodType2}
and PROFIT_TYPE = #{profitType}

SELECT * FROM (
/*流程中*/ SELECT * FROM ( SELECT '${PAGE_DATE_STATUS03}' statusValid, T1.TOTLE_TRADE_ID busiCode, T1.PS cashType,
NVL(T1.SEC_MANAGE_ACCT_ID, T1.CHL_ID) SEC_MANAGE_ACCT_ID, CASE WHEN T1.CHL_ID IS NOT NULL THEN 1 ELSE 0 end channel,
nvl(SAI.SEC_ACCT_NAME, fp.FINPROD_NAME) secAcctName,
T4.FINPROD_MARKET_ID, T4.FINPROD_ABBR finprodAbbr, to_char(T1.VDATE, 'yyyy-MM-dd') vDate/*计息开始日*/, to_char(T1.MDATE, 'yyyy-MM-dd') mDate/*计息结束日*/, to_char(T1.SETTLE_DATE, 'yyyy-MM-dd') TRADE_DATE/*资金到账日*/, T1.SHARE_AMT*100 qty, null PAY_DATE, T3.THEORY_AMT fpriceAmt/*理论本息总额*/,
T1.FPRICE_AMT TRADE_AMT/*实收本息总额*/,
SI.INSTITUTION_NAME institutionName, /*所属机构*/ T1.INSTITUTION_CODE institutionCode,
t3.PA_BUSS_TYPE, T1.FINPROD_ID, T1.WORKFLOW_ID FROM WFL_TRD_FIN_PRODUCT_DEAL_TOTAL T1 LEFT JOIN WFL_TRD_DEAL_TOTAL_ADD wtdta on t1.totle_trade_ID = WTDTA.TOTLE_TRADE_ID
LEFT JOIN WFL_PA_TRD_FIN_DEAL_TOTAL T3 ON T1.TOTLE_TRADE_ID = T3.TOTLE_TRADE_ID LEFT JOIN FIN_PRODUCT T4 ON T1.FINPROD_ID = T4.FINPROD_ID
LEFT JOIN STL_SEC_ACCT_INFO SAI ON T1.SEC_MANAGE_ACCT_ID = SAI.SEC_ACCT_ID LEFT JOIN FIN_PRODUCT FP ON T1.CHL_ID = FP.FINPROD_ID
LEFT JOIN SYS_INSTITUTION SI ON T1.INSTITUTION_CODE = SI.INSTITUTION_CODE
WHERE T4.FINPROD_TYPE2 = #{FINPROD_TYPE_TGF01} AND nvl(T1.IS_OVERDUE_DEAL,#{YESNO_N}) = #{YESNO_N} AND wtdta.MP_FINPROD_ID IS NULL AND T1.P_TRADE_ID IS NULL/*撤销流程中的数据不展示*/ AND T1.P_TOTLE_TRADE_ID IS NULL
AND T1.TOTLE_TRADE_ID = #{busiCode}
AND (FP.FINPROD_ID IN
null) OR FP.FINPROD_ID in (
#{item}
)
AND (EXISTS( select 1 from WFL_TRD_FIN_PRODUCT_DEAL_TOTAL DEAL where DEAL.P_TOTLE_TRADE_ID = T1.TOTLE_TRADE_ID and DEAL.PORTFOLIO_ID
) or T1.PS='T39') ORDER BY T1.MDATE DESC )
UNION ALL
/*待处理*/ SELECT * FROM ( select '${PAGE_DATE_STATUS01}' statusValid, null busiCode, listagg(t8.CASH_TYPE, ',') within group ( order by t8.CASH_TYPE ) CASH_TYPE,
t8.SEC_ACCT_ID secManageAcctId, CASE WHEN fp.FINPROD_NAME IS NOT NULL THEN 1 ELSE 0 end channel,
nvl(SAI.SEC_ACCT_NAME, fp.FINPROD_NAME) secAcctName,
t10.FINPROD_MARKET_ID, t10.FINPROD_ABBR finprodAbbr, to_char(min(t8.VDATE), 'yyyy-MM-dd') vDate, to_char(t8.MDATE, 'yyyy-MM-dd') mDate, null tradeDate, t8.qty*100 qty, to_char(t8.PAY_DATE, 'yyyy-MM-dd') PAY_DATE, ROUND(SUM(t8.fpriceAmt), 2) fpriceAmt, null TRADE_AMT,
SI.INSTITUTION_NAME institutionName, /*所属机构*/
#{institutionCode} institutionCode,
'' institutionCode,
null PA_BUSS_TYPE, T8.FINPROD_ID, NULL WORKFLOW_ID from ( select T6.FINPROD_ID, SUM(T6.AMOUNT) QTY,/*考虑投资目的数量合并*/ T6.CASH_TYPE, T6.CASH_ID, T6.VDATE, T6.MDATE, SUM(T6.CASH_AMT * T6.AMOUNT) fpriceAmt,/*理论本息总额*/ case t6.CASH_TYPE when '${CASH_CLASS_TYPE01}' then 0 else ROUND(SUM(T6.PRIN_AMT * T6.AMOUNT), 2) end prinAmt,/*还本金额*/ T6.SEC_ACCT_ID, ROUND(SUM(t6.INT_AMT * T6.AMOUNT), 2) intAmt,/*理论利息*/ t6.PAY_DATE from ( select * from ( SELECT T1.FINPROD_ID, DECODE(T1.HODING_TYPE, '06', T1.AMOUNT*-1, '11', T1.AMOUNT*-1, T1.AMOUNT) AMOUNT, T1.SEC_ACCT_ID, t2.vdate, t2.mdate, t2.cash_amt, t2.prin_amt, t2.int_amt, t2.cash_id, t2.cash_type, t2.pay_date
FROM PTL_SEC_POSITION T1 INNER JOIN FIN_CASH_PLAN T2 ON T1.FINPROD_ID = T2.FINPROD_ID AND T2.FINPROD_TYPE2 = #{FINPROD_TYPE_TGF01} AND t1.CDATE < t2.MDATE LEFT JOIN PTL_PORTFOLIO pp on pp.PORTFOLIO_ID = T1.PORTFOLIO_ID
INNER JOIN DATA_AUTH_NOTIFY_INST dani on dani.BUSINESS_ID = T1.PORTFOLIO_ID AND dani.DATA_TYPE ='PTL01' AND dani.model_type ='02' AND dani.INSTITUTION_CODE=#{institutionCode}
T1.AMOUNT > 0 AND T1.HODING_TYPE IN ('03', '05', '06', '11') and nvl(pp.PARENT_PORTFOLIO_ID, 'null') = 'null'
AND (instr(#{cashTypeSb}, T2.CASH_TYPE) > 0)
AND t1.finprod_id=#{finprodId}
and T2.CASH_TYPE IN (#{CASH_CLASS_TYPE01},#{CASH_CLASS_TYPE02},#{CASH_CLASS_TYPE03},#{CASH_CLASS_TYPE04})
and (t2.INT_AMT > 0 or t2.PRIN_AMT > 0) and t2.mdate = (select min(tt.mdate) from FIN_CASH_PLAN tt where tt.finprod_id =t1.finprod_id and Tt.FINPROD_TYPE2 = 'F01' AND tt.MDATE > t1.CDATE AND Tt.PAY_DATE >= #{PLATEFORM_DATE} and Tt.CASH_TYPE IN ('01', '02', '03', '04') and (tt.INT_AMT > 0 or t2.PRIN_AMT > 0) )
/*不存在生效的交易*/ and NOT EXISTS (SELECT 1 FROM TRD_FIN_PRODUCT_DEAL_TOTAL TPDA LEFT JOIN TRD_DEAL_TOTAL_ADD TDTA ON TPDA.TOTLE_TRADE_ID = TDTA.TOTLE_TRADE_ID where TDTA.MP_FINPROD_ID IS NULL AND TPDA.TRADE_STATUS = #{TRADE_STATUS01} AND TPDA.BUSI_TYPE = #{TRD10} AND TPDA.IS_CANCEL = #{YESNO_N} and T2.MDATE = TPDA.MDATE AND TPDA.FINPROD_ID = T1.FINPROD_ID AND T1.PORTFOLIO_ID =TPDA.PORTFOLIO_ID
AND TPDA.INSTITUTION_CODE = #{institutionCode}
AND (TPDA.SEC_MANAGE_ACCT_ID = T1.SEC_ACCT_ID OR TPDA.CHL_ID = T1.SEC_ACCT_ID)) /*不存在流程中的当期或之前的交易*/ AND NOT EXISTS (SELECT 1 FROM WFL_TRD_FIN_PRODUCT_DEAL_TOTAL TPDA LEFT JOIN WFL_TRD_DEAL_TOTAL_ADD TDTA ON TPDA.TOTLE_TRADE_ID = TDTA.TOTLE_TRADE_ID where TDTA.MP_FINPROD_ID IS NULL AND TPDA.TRADE_STATUS = #{TRADE_STATUS01} AND TPDA.BUSI_TYPE = #{TRD10} AND TPDA.IS_CANCEL = #{YESNO_N} and T2.MDATE >= TPDA.MDATE AND TPDA.FINPROD_ID = T1.FINPROD_ID AND T1.PORTFOLIO_ID =TPDA.PORTFOLIO_ID AND (TPDA.SEC_MANAGE_ACCT_ID = T1.SEC_ACCT_ID OR TPDA.CHL_ID = T1.SEC_ACCT_ID))
AND NOT EXISTS ( SELECT 1 FROM PTL_SEC_POSITION tpsp where tpsp.HODING_TYPE = T1.HODING_TYPE and tpsp.PORTFOLIO_ID = T1.PORTFOLIO_ID and tpsp.SEC_ACCT_ID = T1.SEC_ACCT_ID and tpsp.FINPROD_ID = T1.FINPROD_ID and tpsp.CDATE > T1.CDATE and tpsp.CDATE < t2.MDATE ) and T2.PAY_DATE >= #{PLATEFORM_DATE}
AND (T1.SEC_ACCT_ID IN
null) OR T1.SEC_ACCT_ID in (
#{item}
)
and T1.PORTFOLIO_ID
null) OR T1.PORTFOLIO_ID IN (
#{item}
)
AND T1.SEC_ACCT_ID = #{secManageAcctId}
)
) T6
AND T6.MDATE >= to_date(#{mdateStart}, 'yyyy-MM-dd')
AND T6.MDATE <= to_date(#{mdateEnd}, 'yyyy-MM-dd')
GROUP BY T6.FINPROD_ID, T6.CASH_TYPE, T6.CASH_ID, T6.VDATE, T6.MDATE, T6.CASH_AMT, T6.PRIN_AMT,/*还本金额*/ T6.SEC_ACCT_ID, t6.INT_AMT, t6.PAY_DATE ) T8 LEFT JOIN FIN_PRODUCT T10 ON T10.FINPROD_ID = T8.FINPROD_ID
LEFT JOIN STL_SEC_ACCT_INFO SAI ON T8.SEC_ACCT_ID = SAI.SEC_ACCT_ID LEFT JOIN FIN_PRODUCT FP ON T8.SEC_ACCT_ID = FP.FINPROD_ID
LEFT JOIN SYS_INSTITUTION SI ON SI.INSTITUTION_CODE = #{institutionCode}
LEFT JOIN SYS_INSTITUTION SI ON SI.INSTITUTION_CODE = ''
where t8.PAY_DATE >= #{PLATEFORM_DATE} GROUP BY t8.SEC_ACCT_ID,SAI.SEC_ACCT_NAME, fp.FINPROD_NAME, t10.FINPROD_MARKET_ID, t10.FINPROD_ABBR, t8.MDATE, t8.qty, t8.PAY_DATE,T8.FINPROD_ID,SI.INSTITUTION_NAME ORDER BY T8.MDATE )
AND CASH_TYPE = #{cashType}
AND (instr(CASH_TYPE, #{cashType}) > 0)
AND tradeDate >= to_date(#{tradeDateStart}, 'yyyy-MM-dd')
AND tradeDate <= to_date(#{tradeDateEnd}, 'yyyy-MM-dd')
UNION ALL
/*有效数据*/ SELECT * FROM ( SELECT '${PAGE_DATE_STATUS05}' statusValid, T1.TOTLE_TRADE_ID busiCode, T1.PS cashType,
NVL(T1.SEC_MANAGE_ACCT_ID, T1.CHL_ID) SEC_MANAGE_ACCT_ID,
CASE WHEN T1.CHL_ID IS NOT NULL THEN 1 ELSE 0 end channel,
DECODE(t1.ps,'T39', NVL2( T1.CHL_ID,fp.FINPROD_NAME,( SELECT regexp_replace(listagg( ssai.sec_acct_name, ',') within group ( order by ssai.sec_acct_name ),'([^,]+)(,\1)*(,|$)','\1\3') FROM trd_product_deal tpd LEFT JOIN trd_fin_product_deal_total total ON tpd.TOTLE_TRADE_ID = total.TOTLE_TRADE_ID LEFT JOIN STL_SEC_ACCT_INFO ssai ON tpd.sec_manage_acct_id = ssai.sec_acct_id WHERE total.P_TOTLE_TRADE_ID = t1.TOTLE_TRADE_ID ) ) , nvl(SAI.SEC_ACCT_NAME, fp.FINPROD_NAME) ) secAcctName,
T4.FINPROD_MARKET_ID, T4.FINPROD_ABBR finprodAbbr, to_char(T1.VDATE, 'yyyy-MM-dd') vDate/*计息开始日*/, to_char(T1.MDATE, 'yyyy-MM-dd') mDate/*计息结束日*/, to_char(T1.SETTLE_DATE, 'yyyy-MM-dd') TRADE_DATE/*资金到账日*/, T1.SHARE_AMT*100 qty, to_char(t1.pay_date, 'yyyy-MM-dd') PAY_DATE, T3.THEORY_AMT fpriceAmt/*理论本息总额*/,
T1.FPRICE_AMT TRADE_AMT/*实收本息总额*/,
SI.INSTITUTION_NAME institutionName, /*所属机构*/ T1.INSTITUTION_CODE institutionCode,
NVL(t3.PA_BUSS_TYPE,T1.TG_BUSI_TYPE) PA_BUSS_TYPE,
T1.FINPROD_ID, NULL WORKFLOW_ID FROM TRD_FIN_PRODUCT_DEAL_TOTAL T1 LEFT JOIN TRD_DEAL_TOTAL_ADD wtdta on t1.totle_trade_ID = WTDTA.TOTLE_TRADE_ID
LEFT JOIN PA_TRD_FIN_PRODUCT_DEAL_TOTAL T3 ON T1.TOTLE_TRADE_ID = T3.TOTLE_TRADE_ID LEFT JOIN FIN_PRODUCT T4 ON T1.FINPROD_ID = T4.FINPROD_ID
LEFT JOIN STL_SEC_ACCT_INFO SAI ON T1.SEC_MANAGE_ACCT_ID = SAI.SEC_ACCT_ID LEFT JOIN FIN_PRODUCT FP ON T1.CHL_ID = FP.FINPROD_ID
LEFT JOIN SYS_INSTITUTION SI ON T1.INSTITUTION_CODE = SI.INSTITUTION_CODE
WHERE T1.TRADE_STATUS = #{TRADE_STATUS01} AND nvl(T1.IS_OVERDUE_DEAL,#{YESNO_N}) = #{YESNO_N} AND wtdta.MP_FINPROD_ID IS NULL AND T1.IS_CANCEL = #{YESNO_N} AND T1.FINPROD_TYPE2 = #{FINPROD_TYPE_TGF01} AND T1.PS NOT IN ('T75','T76','T77')
AND T1.TOTLE_TRADE_ID = #{busiCode}
AND (FP.FINPROD_ID IN
null) OR FP.FINPROD_ID in (
#{item}
)
AND T1.P_TOTLE_TRADE_ID IS NULL
AND (EXISTS( select 1 from TRD_FIN_PRODUCT_DEAL_TOTAL DEAL where DEAL.P_TOTLE_TRADE_ID = T1.TOTLE_TRADE_ID and DEAL.PORTFOLIO_ID
) or T1.PS='T39') ORDER BY T1.MDATE DESC )
/*撤销数据*/
UNION ALL
SELECT * FROM ( SELECT '${PAGE_DATE_STATUS06}' statusValid, T1.P_TRADE_ID busiCode, T1.PS cashType,
NVL(T1.SEC_MANAGE_ACCT_ID, T1.CHL_ID) SEC_MANAGE_ACCT_ID,
CASE WHEN T1.CHL_ID IS NOT NULL THEN 1 ELSE 0 end channel,
DECODE(t1.ps,'T39', NVL2( T1.CHL_ID,fp.FINPROD_NAME,( SELECT regexp_replace(listagg( ssai.sec_acct_name, ',') within group ( order by ssai.sec_acct_name ),'([^,]+)(,\1)*(,|$)','\1\3') FROM trd_product_deal tpd LEFT JOIN trd_fin_product_deal_total total ON tpd.TOTLE_TRADE_ID = total.TOTLE_TRADE_ID LEFT JOIN STL_SEC_ACCT_INFO ssai ON tpd.sec_manage_acct_id = ssai.sec_acct_id WHERE total.P_TOTLE_TRADE_ID = t1.p_TRADE_ID AND tpd.trade_status = t1.trade_status) ) , nvl(SAI.SEC_ACCT_NAME, fp.FINPROD_NAME) ) secAcctName,
T4.FINPROD_MARKET_ID, T4.FINPROD_ABBR finprodAbbr, to_char(T1.VDATE, 'yyyy-MM-dd') vDate/*计息开始日*/, to_char(T1.MDATE, 'yyyy-MM-dd') mDate/*计息结束日*/, to_char(T1.SETTLE_DATE, 'yyyy-MM-dd') TRADE_DATE/*资金到账日*/, T1.SHARE_AMT*100 qty, to_char(t1.pay_date, 'yyyy-MM-dd') PAY_DATE, T3.THEORY_AMT fpriceAmt/*理论本息总额*/, T1.TRADE_AMT/*实收本息总额*/,
SI.INSTITUTION_NAME institutionName, /*所属机构*/ T1.INSTITUTION_CODE institutionCode,
NVL(t3.PA_BUSS_TYPE,T1.TG_BUSI_TYPE) PA_BUSS_TYPE, T1.FINPROD_ID, NULL WORKFLOW_ID FROM TRD_FIN_PRODUCT_DEAL_TOTAL T1 LEFT JOIN TRD_DEAL_TOTAL_ADD wtdta on t1.totle_trade_ID = WTDTA.TOTLE_TRADE_ID
LEFT JOIN PA_TRD_FIN_PRODUCT_DEAL_TOTAL T3 ON T1.TOTLE_TRADE_ID = T3.TOTLE_TRADE_ID LEFT JOIN FIN_PRODUCT T4 ON T1.FINPROD_ID = T4.FINPROD_ID
LEFT JOIN STL_SEC_ACCT_INFO SAI ON T1.SEC_MANAGE_ACCT_ID = SAI.SEC_ACCT_ID LEFT JOIN FIN_PRODUCT FP ON T1.CHL_ID = FP.FINPROD_ID
LEFT JOIN SYS_INSTITUTION SI ON T1.INSTITUTION_CODE = SI.INSTITUTION_CODE
WHERE T1.TRADE_STATUS = #{TRADE_STATUS03} AND nvl(T1.IS_OVERDUE_DEAL,#{YESNO_N}) = #{YESNO_N} AND wtdta.MP_FINPROD_ID IS NULL AND T1.BUSI_TYPE = #{TRD10} AND T1.FINPROD_TYPE2 = #{FINPROD_TYPE_TGF01}
AND T1.P_TRADE_ID = #{busiCode}
AND (FP.FINPROD_ID IN
null) OR FP.FINPROD_ID in (
#{item}
)
AND T1.P_TOTLE_TRADE_ID IS NULL
AND (EXISTS( select 1 from TRD_FIN_PRODUCT_DEAL_TOTAL DEAL where DEAL.P_TOTLE_TRADE_ID = T1.TOTLE_TRADE_ID and DEAL.PORTFOLIO_ID
) or T1.PS='T39') ORDER BY T1.MDATE DESC )
)

SELECT SUM(CC) FROM (
SELECT COUNT(1) cc
FROM TRD_FIN_PRODUCT_DEAL_TOTAL T1
WHERE T1.TRADE_STATUS = #{TRADE_STATUS01}
AND T1.IS_CANCEL = #{YESNO_N}
AND T1.FINPROD_TYPE2 = #{bizType}
AND T1.FINPROD_ID = #{finprodId}

    AND T1.SEC_MANAGE_ACCT_ID = #{secManageAcctId}


    AND T1.CHL_ID = #{chlId}


AND T1.MDATE > TO_DATE(#{mDate}, 'yyyy-MM-dd')
union all
SELECT COUNT(1) cc
FROM WFL_TRD_FIN_PRODUCT_DEAL_TOTAL T1
WHERE T1.TRADE_STATUS = #{TRADE_STATUS01}
AND T1.IS_CANCEL = #{YESNO_N}
AND T1.FINPROD_TYPE2 = #{bizType}
AND T1.FINPROD_ID = #{finprodId}

    AND T1.SEC_MANAGE_ACCT_ID = #{secManageAcctId}


    AND T1.CHL_ID = #{chlId}


AND T1.MDATE > TO_DATE(#{mDate}, 'yyyy-MM-dd')
)

select count(1) from PTL_SEC_POSITION T1 INNER JOIN (select * from FIN_CASH_PLAN T2 WHERE T2.FINPROD_TYPE2 = #{bizType} AND T2.FINPROD_ID = #{finprodId} AND T2.MDATE < to_date(#{mDate}, 'yyyy-MM-dd') and T2.CASH_TYPE IN (#{CASH_CLASS_TYPE01},#{CASH_CLASS_TYPE02},#{CASH_CLASS_TYPE03},#{CASH_CLASS_TYPE04}) and (t2.INT_AMT > 0 or t2.PRIN_AMT > 0) ) T6 ON T1.FINPROD_ID = T6.FINPROD_ID AND T1.HODING_TYPE = #{POSITION_TYPE03} AND t1.CDATE < t6.MDATE and T1.AMOUNT > 0 where NOT EXISTS (SELECT 1 FROM PTL_SEC_POSITION PSP WHERE PSP.FINPROD_ID = T1.FINPROD_ID AND PSP.HODING_TYPE = #{POSITION_TYPE03} AND PSP.CDATE > T1.CDATE AND PSP.CDATE < t6.MDATE)
AND T1.SEC_ACCT_ID = #{secManageAcctId}
AND NOT EXISTS (SELECT 1 FROM TRD_PRODUCT_DEAL tpd LEFT JOIN TRD_FIN_PRODUCT_DEAL_TOTAL TPDA ON tpd.TOTLE_TRADE_ID = tpda.TOTLE_TRADE_ID LEFT JOIN TRD_PRODUCT_DEAL_ADD TPDA1 ON tpd.TRADE_ID = tpda1.TRADE_ID where tpd.TRADE_STATUS = #{TRADE_STATUS01} AND tpd.IS_CANCEL = #{YESNO_N} and T6.CASH_ID = tpd.CASH_ID and T6.MDATE = tpd.MDATE AND (TPDA.PORTFOLIO_ID = T1.PORTFOLIO_ID or tpda1.PORTFOLIO_ID = t1.PORTFOLIO_ID)) AND NOT EXISTS (SELECT 1 FROM WFL_TRD_PRODUCT_DEAL tpd LEFT JOIN WFL_TRD_FIN_PRODUCT_DEAL_TOTAL TPDA on tpd.TOTLE_TRADE_ID = tpda.TOTLE_TRADE_ID LEFT JOIN TRD_PRODUCT_DEAL_ADD TPDA1 ON tpd.TRADE_ID = tpda1.TRADE_ID where T6.CASH_ID = tpd.CASH_ID and T6.MDATE >= tpd.MDATE AND (TPDA.PORTFOLIO_ID = T1.PORTFOLIO_ID or tpda1.PORTFOLIO_ID = t1.PORTFOLIO_ID))

select.if:
SELECT
cash_id,
CASH_TYPE,
PORTFOLIO_ID,
PORTFOLIO_NAME,
INVEST_YESORNO,
FINPROD_ID,
INV_AIM,
CDATE,
SUM(AMOUNT) AMOUNT,
vDate,
mDate,
yield,
CALC_RULE
FROM (
SELECT
listagg(t5.CASH_TYPE, ',') within group ( order by t5.CASH_ID ) CASH_TYPE,
listagg(t5.CASH_ID, ',') within group ( order by t5.CASH_ID ) CASH_ID,
T1.PORTFOLIO_ID,
pp.PORTFOLIO_NAME,
pp.INVEST_YESORNO,
T1.FINPROD_ID,

    DECODE(T1.INV_AIM,'SELL','999999',T1.INV_AIM) AS INV_AIM,

    /*债券必须有投资目的，这个用来区分融入和其他*/
    T1.CDATE,

    DECODE(T1.HODING_TYPE, '06', T1.AMOUNT*-1,'11', T1.AMOUNT*-1, T1.AMOUNT) AMOUNT,

'${vDate}' vDate,
'${mDate}' mDate,
'${yield}' yield,
/*现金流支付规则.支付频率 付息周期*/ T4.PAY_CYCLE CALC_RULE
/*检索对象 组合持仓*/ FROM PTL_SEC_POSITION T1
/*left join 标的类金融产品*/ LEFT JOIN FIN_PRODUCT T2
/*on 组合持仓.金融产品代码 = 标的类金融产品.金融产品代码*/ ON T1.FINPROD_ID = T2.FINPROD_ID
/*left join 现金流信息*/ LEFT JOIN FIN_CASH_INFO T3
/*on 标的类金融产品.金融产品代码 = 现金流信息.业务代码*/ ON T1.FINPROD_ID = T3.FINPROD_ID
/*and 现金流信息.现金流一级类型 = 数据字典缓存.现金流一级类型.利息*/ AND T3.CASH_TYPE_1 = #{CASH_TYPE_1_02}
/*and 现金流信息.现金流二级类型 = 数据字典缓存.现金流二级类型.利息*/ AND T3.CASH_TYPE_2 = #{CASH_TYPE_2_C02}
/*left join 现金流支付规则*/ LEFT JOIN FIN_CASH_PAY_RULE T4
/*on 现金流信息.现金流代码 = 现金流支付规则.现金流代码*/ ON T3.CASH_ID = T4.CASH_ID
/*and 生效日期 小于等于 传参.调整后计算结束日*/ AND T4.EFF_DATE <= #{adjustMDate}
LEFT JOIN FIN_CASH_PLAN T5 ON T1.FINPROD_ID = T5.FINPROD_ID AND T5.MDATE = #{adjustMDate}
LEFT JOIN PTL_PORTFOLIO pp on pp.PORTFOLIO_ID = T1.PORTFOLIO_ID
/*检索条件 金融产品代码 = 传参.金融产品代码*/ where T1.FINPROD_ID = #{finprodId}
    /*and 持仓类型 = 数据字典缓存.持仓类型.实际*/ 

    AND T1.HODING_TYPE IN ('03', '05', '06','11')

/*and 组合持仓.日期 = 平台日*/ AND t1.CDATE < #{adjustMDate}
 AND T1.SEC_ACCT_ID = #{secAcctId}
and T1.AMOUNT > 0
AND nvl(pp.PARENT_PORTFOLIO_ID,'null') = 'null'

AND NOT EXISTS (
SELECT 1 FROM PTL_SEC_POSITION tpsp
where tpsp.HODING_TYPE = T1.HODING_TYPE
and tpsp.PORTFOLIO_ID = T1.PORTFOLIO_ID
and tpsp.SEC_ACCT_ID = T1.SEC_ACCT_ID
and tpsp.FINPROD_ID = T1.FINPROD_ID
and tpsp.CDATE > T1.CDATE
and tpsp.CDATE < #{adjustMDate}
)
/*不存在生效的交易*/
and NOT EXISTS (SELECT 1 FROM TRD_FIN_PRODUCT_DEAL_TOTAL TPDA
LEFT JOIN TRD_DEAL_TOTAL_ADD TDTA ON TPDA.TOTLE_TRADE_ID = TDTA.TOTLE_TRADE_ID
where TDTA.MP_FINPROD_ID IS NULL
AND TPDA.TRADE_STATUS = #{TRADE_STATUS01}
AND TPDA.BUSI_TYPE = #{TRD10}
AND TPDA.IS_CANCEL = #{YESNO_N} and TO_DATE(#{mDate}, 'YYYY-MM-DD') = TPDA.MDATE
AND TPDA.FINPROD_ID = T1.FINPROD_ID
AND T1.PORTFOLIO_ID =TPDA.PORTFOLIO_ID
AND (TPDA.CHL_ID = T1.SEC_ACCT_ID OR TPDA.SEC_MANAGE_ACCT_ID = T1.SEC_ACCT_ID))
/*不存在流程中的当期或之前的交易*/
AND NOT EXISTS (SELECT 1 FROM WFL_TRD_FIN_PRODUCT_DEAL_TOTAL TPDA
LEFT JOIN WFL_TRD_DEAL_TOTAL_ADD TDTA ON TPDA.TOTLE_TRADE_ID = TDTA.TOTLE_TRADE_ID
where TDTA.MP_FINPROD_ID IS NULL
AND TPDA.TRADE_STATUS = #{TRADE_STATUS01}
AND TPDA.BUSI_TYPE = #{TRD10}
AND TPDA.IS_CANCEL = #{YESNO_N} and TO_DATE(#{mDate}, 'YYYY-MM-DD') >= TPDA.MDATE
AND TPDA.FINPROD_ID = T1.FINPROD_ID
AND T1.PORTFOLIO_ID =TPDA.PORTFOLIO_ID
AND (TPDA.CHL_ID = T1.SEC_ACCT_ID OR TPDA.SEC_MANAGE_ACCT_ID = T1.SEC_ACCT_ID))

group by
pp.PORTFOLIO_NAME,
T1.PORTFOLIO_ID,
T1.FINPROD_ID,
PP.INVEST_YESORNO,

         DECODE(T1.INV_AIM,'SELL','999999',T1.INV_AIM),

T1.CDATE,
T1.AMOUNT,
T1.HODING_TYPE,
T4.PAY_CYCLE
)
group by cash_id,
CASH_TYPE,
PORTFOLIO_ID,
PORTFOLIO_NAME,
INVEST_YESORNO,
FINPROD_ID,
INV_AIM,
CDATE,
vDate,
mDate,
yield,
CALC_RULE
having SUM(AMOUNT) > 0

/*检索项目*/
SELECT
/*汇总交易.组合代码 组合*/
TOTAL.PORTFOLIO_ID,
pp.PORTFOLIO_NAME,
/*现金流支付规则.支付频率 付息周期*/

fcpr.PAY_CYCLE CALC_RULE,


TOTAL.INV_AIM,

ROUND(TOTAL.SHARE_AMT*100,2) QTY,

ROUND(PA_TOTAL.THEORY_PRIN,2) prinAmtTheory,
/*金融产品交易扩展2.还本金额/理论利息 还本金额*/
ROUND(TOTAL.PRIN_AMT,2) returnAmount,
/*金融产品交易汇总业务流程表.起息日 计息开始日*/
to_char(TOTAL.VDATE, 'yyyy-MM-dd') vDate,
/*金融产品交易汇总业务流程表.到期日 计息结束日*/
to_char(TOTAL.MDATE, 'yyyy-MM-dd') mDate,
/*金融产品交易汇总扩展业务流程表.区间票面利率*/
PA_TOTAL.RATE*100 yield,
ROUND(PA_TOTAL.THEORY_INT,2) intAmtTheory,

ROUND(TOTAL.INT_AMT,2) intAmt,
ROUND(TOTAL.FEE_AMT,2) channelFee

    FROM WFL_TRD_FIN_PRODUCT_DEAL_TOTAL TOTAL
    LEFT JOIN WFL_PA_TRD_FIN_DEAL_TOTAL PA_TOTAL ON TOTAL.TOTLE_TRADE_ID = PA_TOTAL.TOTLE_TRADE_ID


    FROM TRD_FIN_PRODUCT_DEAL_TOTAL TOTAL
    LEFT JOIN PA_TRD_FIN_PRODUCT_DEAL_TOTAL PA_TOTAL ON TOTAL.TOTLE_TRADE_ID = PA_TOTAL.TOTLE_TRADE_ID

LEFT JOIN PTL_PORTFOLIO pp on pp.PORTFOLIO_ID = TOTAL.PORTFOLIO_ID
LEFT JOIN FIN_CASH_INFO fci ON TOTAL.FINPROD_ID = fci.FINPROD_ID
AND fci.CASH_TYPE_1 = #{CASH_TYPE_1_02} AND fci.CASH_TYPE_2 = #{CASH_TYPE_2_C02}
LEFT JOIN FIN_CASH_PAY_RULE fcpr on fcpr.CASH_ID = fci.CASH_ID and fcpr.EFF_DATE <= TOTAL.MDATE and not
EXISTS (
select 1 from FIN_CASH_PAY_RULE fcpr_2
where fcpr_2.EFF_DATE > fcpr.EFF_DATE
and fcpr.CASH_ID = fcpr_2.CASH_ID
and fcpr_2.EFF_DATE <= TOTAL.MDATE
)


    INNER JOIN DATA_AUTH_NOTIFY_INST dani on dani.BUSINESS_ID = TOTAL.PORTFOLIO_ID
    AND dani.DATA_TYPE ='PTL01' AND dani.INSTITUTION_CODE=#{institutionCode}


/*检索条件*/
WHERE

/*金融产品交易1.金融产品代码 = 传参.金融产品代码*/
TOTAL.P_TOTLE_TRADE_ID = #{busiCode}

and nvl(pp.PARENT_PORTFOLIO_ID,'null') = 'null'

and TOTAL.PORTFOLIO_ID

mapper.select:
SELECT
distinct
wtpd.TRADE_ID
FROM
WFL_TRD_PRODUCT_DEAL wtpd
inner join FIN_CASH_PLAN fcp on wtpd.FINPROD_ID = fcp.FINPROD_ID and wtpd.MDATE = FCP.MDATE
and fcp.MDATE < to_date(#{mdate},'yyyy-MM-dd')
where
wtpd.FINPROD_ID= #{finprodId,jdbcType=VARCHAR}

    AND WTPD.CHL_ID = #{chlId}


    AND WTPD.SEC_MANAGE_ACCT_ID = #{chlId}


    AND WTPD.WORKFLOW_ID != #{workflowId}

SELECT
T1.TOTLE_TRADE_ID busiCode
FROM TRD_FIN_PRODUCT_DEAL_TOTAL T1
LEFT JOIN TRD_DEAL_TOTAL_ADD wtdta on t1.totle_trade_ID = WTDTA.TOTLE_TRADE_ID
LEFT JOIN FIN_PRODUCT T4 ON T1.FINPROD_ID = T4.FINPROD_ID
LEFT JOIN FIN_PRODUCT FP ON T1.CHL_ID = FP.FINPROD_ID
WHERE T1.TRADE_STATUS = #{TRADE_STATUS01}
AND nvl(T1.IS_OVERDUE_DEAL,#{YESNO_N}) = #{YESNO_N}
AND wtdta.MP_FINPROD_ID IS NULL
AND T1.IS_CANCEL = #{YESNO_N}
AND T1.FINPROD_TYPE2 = #{FINPROD_TYPE_TGF01}
AND T1.PS='T39'

    AND T4.FINPROD_MARKET_ID = #{finprodMarketId}


    AND T1.CHL_ID = #{chlId}


    and T1.CHL_ID is null


    AND T1.SETTLE_DATE = to_date(#{tradeDate}, 'yyyy-MM-dd')

select temp.*, rownum
from (
         select distinct business_data_pk4 child, business_data_pk5 payDate
         from sys_data_process_mark
         where page_id = 'TrdBondDuration003'
           and business_data_pk3 = #{bizCode,jdbcType=VARCHAR}
     ) temp
where rownum < 2

select wtpd.totle_trade_id
from wfl_trd_fin_product_deal_total wtpd
where wtpd.finprod_id = #{finprodId}
and wtpd.ps =#{ps}

    AND wtpd.chl_id = #{chlId}


    and wtpd.chl_id is null

SELECT DISTINCT A.FINPROD_MARKET_ID id, A.FINPROD_ABBR text, A.FINPROD_ID, A.FINPROD_NAME, A.FINPROD_ABBR, TO_CHAR(A.VDATE, 'yyyy-MM-dd') VDATE, TO_CHAR(A.MDATE, 'yyyy-MM-dd') MDATE, TO_CHAR(A.IDATE, 'yyyy-MM-dd') IDATE, A.TRADE_MARKET, A.CCY, A.CALENDAR_ID, B.TYPE_4 windtypeone, B.TYPE_6,
B.TYPE_9, B.TYPE_10, B.TYPE_11,
to_char(T1.VDATE, 'yyyy-MM-dd') EXERCISE_VDATE, to_char(T1.MDATE, 'yyyy-MM-dd') EXERCISE_MDATE, to_char(T1.ACT_EXERCISE_DATE, 'yyyy-MM-dd') EXERCISE_DATE, T1.EXERCISE_PRICE,
A.IS_RIGHT FROM FIN_PRODUCT A LEFT JOIN FIN_PRODUCT_TYPE B ON B.FINPROD_ID = A.FINPROD_ID LEFT JOIN FIN_PRODUCT_ADD FPA ON FPA.FINPROD_ID = A.FINPROD_ID
INNER JOIN FIN_EXERCISE_PLAN T1 ON T1.FINPROD_ID = A.FINPROD_ID AND T1.EXERCISE_TYPE = '01' and T1.EXERCISE_DATE IS NOT NULL AND T1.ACT_EXERCISE_DATE >= to_date(#{sysDate}, 'yyyy-MM-dd') AND T1.ACT_EXERCISE_DATE = ( SELECT min(TT1.ACT_EXERCISE_DATE) FROM FIN_EXERCISE_PLAN TT1 WHERE TT1.FINPROD_ID = T1.FINPROD_ID AND TT1.ACT_EXERCISE_DATE >= to_date(#{sysDate}, 'yyyy-MM-dd') AND TT1.EXERCISE_TYPE = '01' )
AND NOT EXISTS ( SELECT 1 FROM TRD_FIN_PRODUCT_DEAL_TOTAL TT WHERE TT.FINPROD_ID = A.FINPROD_ID AND TT.VDATE = T1.VDATE AND TT.MDATE = T1.MDATE AND TT.PS='T39' AND TT.IS_CANCEL='N' AND TT.TRADE_STATUS ='01'
and TT.CHL_ID=#{chlId}
) AND NOT EXISTS ( SELECT 1 FROM WFL_TRD_FIN_PRODUCT_DEAL_TOTAL TT WHERE TT.FINPROD_ID = A.FINPROD_ID AND TT.VDATE = T1.VDATE AND TT.MDATE = T1.MDATE AND TT.PS='T39'
AND TT.WORKFLOW_ID != #{workflowId}
)
AND EXISTS ( SELECT 1 FROM ( SELECT T1.PORTFOLIO_ID, T1.SEC_ACCT_ID, T1.FINPROD_ID, T1.CDATE, DECODE(T1.HODING_TYPE, '06', T1.AMOUNT*-1, '04', T1.AMOUNT*-1, T1.AMOUNT) AMOUNT FROM PTL_SEC_POSITION T1 INNER JOIN FIN_EXERCISE_PLAN E1 ON E1.FINPROD_ID = T1.FINPROD_ID AND E1.EXERCISE_TYPE = '01' and E1.EXERCISE_DATE IS NOT NULL AND E1.EXERCISE_DATE <= to_date(#{sysDate}, 'yyyy-MM-dd') AND NOT EXISTS ( SELECT 1 FROM FIN_EXERCISE_PLAN TT1 WHERE TT1.FINPROD_ID = E1.FINPROD_ID AND E1.EXERCISE_DATE <= to_date(#{sysDate}, 'yyyy-MM-dd') AND TT1.EXERCISE_TYPE = '01' AND TT1.EXERCISE_DATE > E1.EXERCISE_DATE )
T1.HODING_TYPE IN ('03', '04', '06', '08')
and T1.SEC_ACCT_ID = #{chlId}
AND NOT EXISTS (SELECT 1 FROM FIN_PRODUCT FP WHERE FP.FINPROD_ID = T1.SEC_ACCT_ID)
AND T1.PORTFOLIO_ID IN (select PORTFOLIO_ID from PTL_PORTFOLIO_AUTHORITY where USER_ID = #{loginUserName}) AND NOT EXISTS (SELECT 1 FROM PTL_SEC_POSITION TT1 WHERE T1.PORTFOLIO_ID = TT1.PORTFOLIO_ID AND T1.SEC_ACCT_ID = TT1.SEC_ACCT_ID AND T1.FINPROD_ID = TT1.FINPROD_ID AND T1.BRANCH = TT1.BRANCH AND T1.INV_AIM = TT1.INV_AIM AND T1.HODING_TYPE = TT1.HODING_TYPE AND T1.CDATE < TT1.CDATE and tt1.cdate <= E1.EXERCISE_DATE )
UNION ALL SELECT T1.PORTFOLIO_ID, T1.SEC_ACCT_ID, T1.FINPROD_ID, T1.CDATE, T1.AMOUNT FROM PTL_SEC_POSITION_FLOW T1
AND T1.HODING_TYPE IN ('01')
and T1.SEC_ACCT_ID = #{chlId}
AND NOT EXISTS (SELECT 1 FROM FIN_PRODUCT FP WHERE FP.FINPROD_ID = T1.SEC_ACCT_ID)
AND T1.PORTFOLIO_ID IN (select PORTFOLIO_ID from PTL_PORTFOLIO_AUTHORITY where USER_ID = #{loginUserName})
) PSP INNER JOIN PTL_PORTFOLIO PP ON PSP.PORTFOLIO_ID = PP.PORTFOLIO_ID AND PP.INVEST_YESORNO = 'Y' WHERE PSP.FINPROD_ID = A.FINPROD_ID AND T1.EXERCISE_DATE >= PSP.CDATE GROUP BY PSP.PORTFOLIO_ID, PSP.SEC_ACCT_ID, PSP.FINPROD_ID )
( A.FINPROD_MARKET_ID LIKE CONCAT('%', CONCAT(#{search}, '%')) or A.FINPROD_NAME LIKE CONCAT('%', CONCAT(#{search}, '%')) )
AND A.FINPROD_MARKET_ID = #{initValue}
AND A.IS_RIGHT = 'Y'
AND A.FINPROD_TYPE2 = #{finprodType}
AND FPA.APPEAR_MARKET_ID IS null

/*流程中*/ SELECT DISTINCT T1.TOTLE_TRADE_ID id, T1.TOTLE_TRADE_ID text FROM WFL_TRD_FIN_PRODUCT_DEAL_TOTAL T1 LEFT JOIN WFL_TRD_DEAL_TOTAL_ADD wtdta on t1.totle_trade_ID = WTDTA.TOTLE_TRADE_ID LEFT JOIN WFL_PA_TRD_FIN_DEAL_TOTAL T3 ON T1.TOTLE_TRADE_ID = T3.TOTLE_TRADE_ID LEFT JOIN FIN_PRODUCT T4 ON T1.FINPROD_ID = T4.FINPROD_ID WHERE T4.FINPROD_TYPE2 = #{FINPROD_TYPE_TGF01} AND nvl(T1.IS_OVERDUE_DEAL,#{YESNO_N}) = #{YESNO_N} AND wtdta.MP_FINPROD_ID IS NULL AND T1.P_TRADE_ID IS NULL/*撤销流程中的数据不展示*/ AND T1.P_TOTLE_TRADE_ID IS NULL AND (EXISTS( select 1 from WFL_TRD_FIN_PRODUCT_DEAL_TOTAL DEAL where DEAL.P_TOTLE_TRADE_ID = T1.TOTLE_TRADE_ID and DEAL.PORTFOLIO_ID
) or T1.PS='T39')
and (instr(TOTLE_TRADE_ID, #{search}) > 0)
UNION ALL /*有效数据*/ SELECT DISTINCT T1.TOTLE_TRADE_ID id, T1.TOTLE_TRADE_ID text FROM TRD_FIN_PRODUCT_DEAL_TOTAL T1 LEFT JOIN TRD_DEAL_TOTAL_ADD wtdta on t1.totle_trade_ID = WTDTA.TOTLE_TRADE_ID LEFT JOIN PA_TRD_FIN_PRODUCT_DEAL_TOTAL T3 ON T1.TOTLE_TRADE_ID = T3.TOTLE_TRADE_ID LEFT JOIN FIN_PRODUCT T4 ON T1.FINPROD_ID = T4.FINPROD_ID LEFT JOIN PTL_TRADE PT ON T1.FINPROD_ID = PT.BUSI_NO LEFT JOIN PTL_PORTFOLIO PP ON PT.PORTFOLIO_ID = PP.PORTFOLIO_ID WHERE T1.TRADE_STATUS = #{TRADE_STATUS01} AND nvl(T1.IS_OVERDUE_DEAL,#{YESNO_N}) = #{YESNO_N} AND wtdta.MP_FINPROD_ID IS NULL AND T1.IS_CANCEL = #{YESNO_N} AND T1.FINPROD_TYPE2 = #{FINPROD_TYPE_TGF01} AND T1.PS NOT IN ('T75','T76','T77') AND T1.P_TOTLE_TRADE_ID IS NULL
AND (EXISTS( select 1 from TRD_FIN_PRODUCT_DEAL_TOTAL DEAL where DEAL.P_TOTLE_TRADE_ID = T1.TOTLE_TRADE_ID and DEAL.PORTFOLIO_ID
) or T1.PS='T39')
and (instr(TOTLE_TRADE_ID, #{search}) > 0)
UNION ALL /*撤销数据*/ SELECT DISTINCT T1.P_TRADE_ID id, T1.P_TRADE_ID text FROM TRD_FIN_PRODUCT_DEAL_TOTAL T1 LEFT JOIN TRD_DEAL_TOTAL_ADD wtdta on t1.totle_trade_ID = WTDTA.TOTLE_TRADE_ID LEFT JOIN PA_TRD_FIN_PRODUCT_DEAL_TOTAL T3 ON T1.TOTLE_TRADE_ID = T3.TOTLE_TRADE_ID LEFT JOIN FIN_PRODUCT T4 ON T1.FINPROD_ID = T4.FINPROD_ID WHERE T1.TRADE_STATUS = #{TRADE_STATUS03} AND nvl(T1.IS_OVERDUE_DEAL,#{YESNO_N}) = #{YESNO_N} AND wtdta.MP_FINPROD_ID IS NULL AND T1.BUSI_TYPE = #{TRD10} AND T1.FINPROD_TYPE2 = #{FINPROD_TYPE_TGF01} AND (EXISTS( select 1 from TRD_FIN_PRODUCT_DEAL_TOTAL DEAL where DEAL.P_TOTLE_TRADE_ID = T1.TOTLE_TRADE_ID and DEAL.PORTFOLIO_ID
) or T1.PS='T39')
and (instr(P_TRADE_ID, #{search}) > 0)
